\label{prop:Ricci}
Define
\[
 \operatorname{Ric}_g^{\rm v}:=(\operatorname{Ric}_g(X_i,X_j))_{i,j=1}^2.
\]
For \eqref{eq:matrix-ansatz}, with $\ell:=\log\rho$, the mixed components $\operatorname{Ric}_g(Y,X_i)$, $Y\in T\Omega$, vanish, and we have
\begin{equation}\label{eq:matrix-ricci}
 \begin{aligned}
 \operatorname{Ric}_g|_{T\Omega}
 &=K_hh-\operatorname{Hess}_h\ell-\tfrac12d\ell^2
                         -\tfrac12\Phi^*g_{\mathbb H^2},\\
 G^{-1}\operatorname{Ric}_g^{\rm v}
 &=-\tfrac12\rho^{-1}\operatorname{div}_h(\rho G^{-1}dG).
 \end{aligned}
\end{equation}
For a matrix of differential forms, $\operatorname{div}_h$ and $d$ mean entry by entry.

The scalar curvature and volume are
\begin{equation}\label{eq:scalar-volume}
 \begin{aligned}
 S_g&=2K_h-2\rho^{-1}\Delta_h\rho
                  +\tfrac12(|d\ell|_h^2-|d\Phi|_h^2),\\
 dV_g&=\rho\,dA_h\,d\phi_1\,d\phi_2,\qquad\text{and}\qquad
  \operatorname{Vol}(g)=4\pi^2\int_\Omega d\mu.
 \end{aligned}
\end{equation}
For a torus-invariant function $f$, we also have
\begin{equation}\label{eq:geometric-laplacian}
 \Delta_gf=\rho^{-1}\operatorname{div}_h(\rho\nabla_hf)
 =\Delta_hf+\langle d\ell,df\rangle_h.
\end{equation}

\label{prop:reduced}
For \eqref{eq:matrix-ansatz}, with $h=e^{2a}\gamma$ for any metric $\gamma$ conformal to $h$, such as $\gamma=\gamma_\beta$ of \eqref{eq:conic-chart}, the equations
$\operatorname{Ric}_g^{\rm v}=3G$ and $S_g=12$ are equivalent to
\begin{equation}\label{eq:matrix-reduced}
 \begin{aligned}
 \rho^{-1}\Delta_\gamma\rho+6e^{2a}&=0,\\
 \tau_\gamma(\Phi)+d\Phi(\nabla_\gamma\ell)&=0,\\
 \Delta_\gamma a-K_\gamma+\tfrac14(|d\Phi|_\gamma^2-|d\ell|_\gamma^2)&=0.
 \end{aligned}
\end{equation}

\label{rem:remaining-component}
In local coordinates on $\mathbb H^2$, the principal parts of the system \eqref{eq:matrix-reduced} are the scalar Laplacians $\Delta_\gamma$ of $\ell$, of the two coordinates of $\Phi$ and of $a$, so it is elliptic. By \eqref{eq:matrix-ricci}, for a solution of \eqref{eq:matrix-reduced}, the only component of $\operatorname{Ric}_g-3g$ which may not vanish is the trace-free horizontal part
\begin{equation}\label{eq:remaining-component}
 (\operatorname{Ric}_g-3g)|_{T\Omega}
 =-\bigl(\operatorname{Hess}_h\ell+\tfrac12d\ell^2+\tfrac12\Phi^*g_{\mathbb H^2}\bigr)^\circ.
\end{equation}
Imposing its two scalar equations, with second-order part $(\partial_x^2\ell-\partial_y^2\ell,\,2\partial_x\partial_y\ell)$, would make the system overdetermined. Proposition~\ref{prop:recovery} shows that \eqref{eq:remaining-component} vanishes for the solutions of \eqref{eq:matrix-reduced} satisfying the angle conditions \eqref{eq:angle-equalities}, so they solve \eqref{eq:einstein} with $\lambda=3$.

