\label{lem:reduced-map}
There is a neighborhood $\mathcal U_0$ of $0$ in $\mathcal X$ such that the map
\begin{equation}\label{eq:reduced-map}
 \mathcal E:J\times\mathcal U_0\longrightarrow\mathcal Y
\end{equation}
is well defined and smooth. In particular, $\mathcal E_3(\beta,q)(c)=0$ at every corner $c\in\mathcal C$, for every $(\beta,q)\in J\times\mathcal U_0$.

\label{lem:cone-Schauder}
Equip the punctured disk $\{0<R<R_0,\ \theta\in\mathbb R/(2\pi\mathbb Z)\}$ with the reference metric $\gamma_\beta=\frac{1}{3}(dR^2+\beta^2R^2d\theta^2)$ of \eqref{eq:fixed-cone-identification}. Let $u$ be bounded, and suppose
\[
 \Delta_{\gamma_\beta}u=\mathfrak f
\]
weakly on the punctured disk. Assume that $u(R,\theta+\pi)=u(R,\theta)$. For $0<\delta<\frac{2}{\beta}$, if $\mathfrak f\in R^{\delta-2}C^{0,\alpha}_{\mathrm b}$, then $u$ has a limit $u_o$ at the vertex and
\begin{equation}\label{eq:cone-schauder}
 |u_o|+\|u-u_o\|_{R^\delta C^{2,\alpha}_{\mathrm b}(R<\frac{1}{2}R_0)}\leqslant C\bigl(\|u\|_\infty+\|\mathfrak f\|_{R^{\delta-2}C^{0,\alpha}_{\mathrm b}(R<R_0)}\bigr),
\end{equation}
where $C$ depends only on $\alpha$, $R_0$, upper and positive lower bounds for $\beta$, a positive lower bound for $\delta$, and a positive lower bound for $\frac{2}{\beta}-\delta$. The statement also applies componentwise to vector-valued functions. Moreover, for every integer $j\geqslant0$ and every $\delta\in\mathbb R$, if $\Delta_{\gamma_\beta}u=\mathfrak f$ on $\{0<R<R_0\}$, then we have
\begin{equation}\label{eq:annular-estimate}
 \|u\|_{R^\delta C^{j+2,\alpha}_{\mathrm b}(R<\frac{1}{2}R_0)}\leqslant C_j\bigl(\|u\|_{R^\delta L^\infty(R<R_0)}+\|\mathfrak f\|_{R^{\delta-2}C^{j,\alpha}_{\mathrm b}(R<R_0)}\bigr),
\end{equation}
where $\|u\|_{R^\delta L^\infty}:=\sup R^{-\delta}|u|$ and $C_j$ depends only on $j$, $\alpha$, $R_0$, bounds for $\beta^{\pm1}$ and an upper bound for $|\delta|$. The same holds for $\Delta_{\gamma_\beta}+C_1^a\partial_a+C_0$ if $RC_1$ and $R^2C_0$ are bounded in $C^{j,\alpha}_{\mathrm b}$, with $C_j$ depending also on the bounds for $RC_1$ and $R^2C_0$.

Let $I\subset(0,1)$ be a compact interval, put $\beta_I:=\max I$, fix $\varepsilon$ in the interval $\bigl(0,\min\{2,\frac{2}{\beta_I}-2\}\bigr)$, and let $\beta\in I$ and $M>0$. On the punctured disk $\{0<R<R_0\}$, let $\rho>0$ and $a$ be $\mathcal G$-invariant functions, and let $\Phi$ be a $\mathcal G$-equivariant map to $\mathbb H^2$. Put $h:=e^{2a}\gamma_\beta$, $g:=h+\rho\Phi_{ij}\,d\phi_i\,d\phi_j$ and $U:=\Pi_{\Phi_o}\Phi$, and assume that
\begin{enumerate}[label=\textup{(H\arabic*)}]
\item the reduced equations \eqref{eq:matrix-reduced}, in the form \eqref{eq:central-matrix-system} below, hold in the sense of distributions on $\{0<R<R_0\}$, and
\item we have the bound
\begin{equation}\label{eq:central-quantitative-input}
 \|a\|_{L^\infty}+\|\rho\|_{L^\infty}+\|\rho^{-1}\|_{L^\infty}+\|d\rho\|_{L^\infty(\gamma_\beta)}+\|d\Phi\|_{L^\infty(\gamma_\beta)}\leqslant M.
\end{equation}
\end{enumerate}

\label{lem:center-expansion}


Assume (H1) and (H2). Then, on $\{0<R<\frac{1}{2}R_0\}$, we have
\begin{equation}\label{eq:center-refined}
\begin{gathered}
 \rho=\rho(o)-\tfrac12e^{2a(o)}\rho(o)R^2+O_{\mathrm b}(R^{2+\varepsilon}),\\
 a-a(o)=O_{\mathrm b}(R^{2+\varepsilon}),\qquad\text{and}\qquad U=O_{\mathrm b}(R^{2+\varepsilon}),
\end{gathered}
\end{equation}
where, for every $j\geqslant0$, the three remainders are bounded in $R^{2+\varepsilon}C^{j,\alpha}_{\mathrm b}$ by constants depending only on $j$, $I$, $\varepsilon$, $M$, $R_0$ and $\alpha$. Consequently, with the flat product $g^0:=e^{2a(o)}\gamma_\beta+G_{ij}(o)\,d\phi_i\,d\phi_j$ and a constant $C$ depending only on $I$, $\varepsilon$, $M$, $R_0$ and $\alpha$, we have
\begin{equation}\label{eq:center-regularity}
 g-g^0=O_{\mathrm b}(R^2),\qquad C^{-1}g^0\leqslant g\leqslant Cg^0,\qquad |\operatorname{Rm}(g)|_g\leqslant C,\qquad\text{and}\qquad K_h=O_{\mathrm b}(R^2).
\end{equation}

\label{prop:spectrum}
For every metric $g=g_{\beta,q}$ satisfying $\mathcal E(\beta,q)=0$ with $0<\beta\leqslant1$, and every
$f\in H^1(M,g)$ with $\int_M f\,dV_g=0$, we have
\begin{equation}\label{eq:spectral-inequality}
 \int_M|df|_g^2\,dV_g\geqslant4\int_M f^2\,dV_g.
\end{equation}
Here $H^1(M,g)$ is the
completion of $C_c^\infty(M\setminus\Sigma)$ in the norm
$\|f\|_{H^1}^2:=\int_M(f^2+|df|_g^2)\,dV_g$.
Equality in \eqref{eq:spectral-inequality} implies $f=0$.

\label{cmp:comparison-isomorphism}
The operator $P:\mathcal X\to\mathcal Y$ is an isomorphism, with
\begin{equation}\label{cmp:comparison-estimate}
 \|P^{-1}F\|_{\mathcal X}\leqslant C\|F\|_{\mathcal Y}.
\end{equation}
The difference $\mathcal K=L-P$ is compact. Consequently $L$ is Fredholm of index zero.

Let $F\in\mathcal Y$. By Lemma~\ref{lem:shifted-regularity}, the weak solution $f$ of $A_1f=F_1$, and then the weak solution $\xi$ of $A_2\xi=F_2-d\Phi(\nabla_\gamma f)$, have the regularity of the components of $\mathcal X$, with $\|f\|_{\mathcal X}+\|\xi\|_{\mathcal X}\leqslant C\|F\|_{\mathcal Y}$. Indeed, $d\Phi(\nabla_\gamma f)$ is bounded in the second component of $\mathcal Y$ by $C\|f\|_{\mathcal X}$: at $o$ by \eqref{eq:central-domain}, and at the axes by \eqref{eq:divided-even-norm} for $\langle ds,df\rangle_\gamma$ and by the parities of \eqref{eq:connection-form-local} for the transverse component $\langle A_\Phi,df\rangle_\gamma$.

Next, let $b_0$ be an extension of the boundary values $\frac{1}{2}(f\mp\xi_s)$ prescribed by \eqref{eq:conic-boundary} and \eqref{eq:corner-domain}. We choose it as follows: near a corner, $b_0(x,y):=\frac{1}{2}\bigl[f(x,y)+\xi_s(x,0)-\xi_s(0,y)\bigr]$, which has these boundary values since $\xi_s(c)=0$ by \eqref{eq:corner-symmetry}, and near an open rod, $b_0:=\frac{1}{2}(f-\xi_s)$. Patch these extensions near $\partial\Omega$ by a partition of unity, so that $b_0=0$ near $o$, and average over $\mathcal G$. The average keeps the prescribed boundary values, which are $\mathcal G$-invariant because $\mathcal G$ maps rod frames to rod frames. Then $(f,\xi,b_0)\in\mathcal X$, with $\|b_0\|_{\mathcal X}\leqslant C(\|f\|_{\mathcal X}+\|\xi\|_{\mathcal X})$. Since $L$ maps $\mathcal X$ to $\mathcal Y$, $L_3(f,\xi,b_0)$ vanishes at the corners, so $F_3-L_3(f,\xi,b_0)$ belongs to the third component of $\mathcal Y$. Lemma~\ref{lem:shifted-regularity} gives the solution $v$ of $A_3v=F_3-L_3(f,\xi,b_0)$ with $v|_{\partial\Omega}=0$, and $q:=(f,\xi,b_0+v)\in\mathcal X$ satisfies $Pq=F$ and \eqref{cmp:comparison-estimate}.

Conversely, if $Pq=0$ for some $q=(f,\xi,b)\in\mathcal X$, then $f=0$ and $\xi=0$, by uniqueness of the weak solutions, so $b$ vanishes on $\partial\Omega$ and $A_3b=0$, hence $b=0$. So $P$ is an isomorphism.

Away from $o$, compactness of $\mathcal K$ follows from the compact inclusion $C^{2,\alpha}\hookrightarrow C^{0,\alpha}$. Near $o$, the formula for $\mathcal Kq$ and \eqref{eq:central-domain} give a bounded map into $C^{2,\alpha}_{\mathrm b}$, since the background coefficient $e^{2a}$ is bounded in $C^{2,\alpha}_{\mathrm b}$. Since $\nu<2$, the embedding
\begin{equation}\label{cmp:compact-weighted-embedding}
 C^{2,\alpha}_{\mathrm b}\hookrightarrow R^{\nu-2}C^{0,\alpha}_{\mathrm b}
\end{equation}
is compact \cite[Lemma~2.2]{PR00}, so $\mathcal K:\mathcal X\to\mathcal Y$ is compact.

\label{cor:concavity}
Let $g$ be in (C1) or (C2). Then, we have
\begin{equation}\label{eq:concavity}
 \frac{\operatorname{Hess}_h\sqrt\psi}{\sqrt\psi}=\tfrac12(K_h-3)h-\tfrac14B\leqslant-h.
\end{equation}
Consequently $o$ is the only critical point of $\psi$, $\psi(o)=\max\psi=1$, every superlevel set $E_t$ with $0<t<1$ is a closed disk with smooth boundary $\partial E_t=\{\psi=t\}$, and, for $q\in\Omega\setminus\{o\}$, we have
\begin{equation}\label{eq:base-radius}
\begin{gathered}
 4\psi(1-\psi)\leqslant|d\psi|_h^2\leqslant4(1-\psi^2),\qquad
 d_h(o,q)\leqslant\arccos\sqrt{\psi(q)},\qquad d_h(q,\partial\Omega)\leqslant\arcsin\sqrt{\psi(q)},\\
 \text{and}\qquad d_h(q,E_\delta)\leqslant\arcsin\sqrt\delta-\arcsin\sqrt{\psi(q)}\qquad\text{if }0<\psi(q)<\delta<1.
\end{gathered}
\end{equation}
In particular, for $q,q'\in\Omega$, we have
\begin{equation}\label{eq:coord-psi-distance}
 |\psi(q)-\psi(q')|\leqslant2d_h(q,q'),\qquad\text{and}\qquad
 \psi(q)\geqslant\min\bigl\{\tfrac12,\tfrac12d_h(q,\partial\Omega)^2\bigr\}.
\end{equation}

\label{lem:core-retraction}

Let $g$ be in (C1) or (C2). 
For $\delta\in(0,1)$, the  flow of $V_\psi$ in \eqref{eq:level-flow} defines a map $P_\delta$ which does not increase lengths and extends to a retraction of $\overline\Omega$ onto $E_\delta$. Consequently, for $p,q\in E_\delta$, the length distance $d_{E_\delta}$ of $E_\delta$ satisfies
\begin{equation}\label{eq:core-retraction}
 d_{E_\delta}(p,q)=d_{\overline\Omega}(p,q).
\end{equation}

Fix $\tau\in(0,1)$, parametrize the  circle $\{\psi=\tau\}$  by $\Theta\in\mathbb R/2\pi\mathbb Z$, and transport $\Theta$ along the  flow of $V_\psi$ of  \eqref{eq:level-flow}. This identifies $\Omega\setminus\{o\}$ with $(0,1)\times\mathbb R/2\pi\mathbb Z$, with $t:=\psi$ and $\partial_t=V_\psi$. The flow maps level sets to level sets, so  $h(V_\psi,\partial_\Theta)=0$  and $h=\mathsf w^{-1}dt^2+|\partial_\Theta|_h^2\,d\Theta^2$, since $|V_\psi|_h^2=\mathsf w^{-1}$. As $[\partial_t,\partial_\Theta]=0$  and $\operatorname{Hess}_h\psi(\partial_\Theta,\partial_\Theta)=2\sqrt\psi\,\operatorname{Hess}_h\sqrt\psi(\partial_\Theta,\partial_\Theta)<0$ by \eqref{eq:concavity}, we get
\begin{equation}\label{eq:core-coordinates}
 \tfrac12\,\partial_t|\partial_\Theta|_h^2=h(\nabla_{\partial_\Theta}V_\psi,\partial_\Theta)=\frac{\operatorname{Hess}_h\psi(\partial_\Theta,\partial_\Theta)}{\mathsf w}<0.
\end{equation}


Put $P_\delta(t,\Theta):=(\max\{t,\delta\},\Theta)$. For a path $c=(t(s),\Theta(s))$, the image of its part in $\{t<\delta\}$ is $(\delta,\Theta(s))$, of speed $|\dot\Theta\,\partial_\Theta|_h(\delta,\Theta)\leqslant|\dot\Theta\,\partial_\Theta|_h(t,\Theta)\leqslant|\dot c|_h$, by \eqref{eq:core-coordinates}. So $P_\delta$ is $1$-Lipschitz for the length distance of $\Omega$, and it extends to the completion $\overline\Omega$. Paths meeting the rods or corners are limits of interior paths  whose lengths converge to that of the original path, by the smooth rod and corner models \eqref{eq:matrix-smooth-side} and \eqref{eq:matrix-smooth-corner}, so the distance of $\overline\Omega$ is the infimum of the lengths of paths in $\Omega$. Projecting these paths by $P_\delta$ gives $d_{E_\delta}\leqslant d_{\overline\Omega}$ on $E_\delta$, and the reverse inequality is immediate.

\label{prop:Schlafli}

Let $t\mapsto(\beta(t),q(t))$ be a $C^1$ curve in
$\mathbb R\times\mathcal X_\nu^{2,\alpha}$ satisfying
$\mathcal E(\beta(t),q(t))=0$, and let
$g(t)=g_{\beta(t),q(t)}$ be as in
\eqref{eq:perturbed-metric}. Put $V(t):=\operatorname{Vol}(g(t))$ and denote
$\frac{d}{dt}$ by a dot. Then, we have
\begin{equation}\label{eq:Schlafli}
 \dot V=\frac{2\pi}{3}\operatorname{Area}(\Sigma,g)\,\dot\beta.
\end{equation}

\label{prop:noncollapse}
Every metric $g=g_{\beta,q}$ as in \eqref{eq:perturbed-metric} with $0<\beta<1$ and $\mathcal E(\beta,q)=0$
satisfies
\begin{equation}\label{eq:area-volume}
\frac{2\pi\beta}{15}\operatorname{Area}(\Sigma,g)
 \leqslant\operatorname{Vol}(g)\leqslant\frac{2\pi\beta}{3}\operatorname{Area}(\Sigma,g).
\end{equation}

By \eqref{eq:scalar-volume}, we have
\begin{equation}\label{eq:volume-psi}
  \operatorname{Vol}(g)=\operatorname{Area}(\Sigma,g)\int_\Omega\psi\,dA_h.
\end{equation}
By Corollary~\ref{cor:concavity}, $E_t$ is a closed disk with smooth boundary. If $T$ is the unit tangent of $\partial E_t=\{\psi=t\}$ and $n=\nabla\psi/|d\psi|_h$
its inward normal, the geodesic curvature $k_t$ of the level set $\{\psi=t\}$ is then
\[
\begin{aligned}
 k_t=\langle\nabla_TT,n\rangle_h
 &=-\frac{\operatorname{Hess}_h\psi(T,T)}{|d\psi|_h}
 =\frac{t}{|d\psi|_h}\left(3-K_h+\tfrac12B(T,T)\right).
\end{aligned}
\]
Gauss-Bonnet, with the central cone angle $2\pi\beta$, reads
\begin{equation}\label{eq:level-Gauss-Bonnet}
 2\pi\beta=\int_{E_t}K_h\,dA_h+
 \int_{\psi=t}\frac{t}{|d\psi|_h}
       \left(3-K_h+\tfrac12B(T,T)\right)ds_h.
\end{equation}

\emph{Two weighted identities.} The weight $dt$ cancels the curvature contribution, and the weight $2t\,dt$ converts the logarithmic-gradient contribution $\psi^2|d\log\psi|_h^2$ into the Dirichlet energy $|d\psi|_h^2$ of $\psi$. For $p\in\{1,2\}$, integrating \eqref{eq:level-Gauss-Bonnet} against $pt^{p-1}dt$ on $(0,1)$, the coarea formula and Fubini's theorem give
\begin{equation}\label{eq:level-flux}
 2\pi\beta=\int_\Omega\psi^p\bigl(3p+(1-p)K_h+\tfrac p2B(T,T)\bigr)dA_h.
\end{equation}
Here we first integrate \eqref{eq:level-Gauss-Bonnet} for $t\in(\varepsilon,1-\varepsilon)$ and then let $\varepsilon\downarrow0$. The expansions \eqref{eq:matrix-smooth-side} at the rods, \eqref{eq:matrix-smooth-corner} at the corners and \eqref{eq:center-refined} at the center justify the limits.
For $p=1$, $B(T,T)\geqslant0$ gives $2\pi\beta\geqslant3\int_\Omega\psi\,dA_h$, which is the upper bound of \eqref{eq:area-volume}, by \eqref{eq:volume-psi}. For $p=2$, integration by parts, using $\psi=0$ on $\partial\Omega$, \eqref{eq:center-refined} at $o$ and $\Delta_h\psi=-6\psi$, gives $\int_\Omega|d\psi|_h^2\,dA_h=6\int_\Omega\psi^2\,dA_h$. With $B(T,T)\leqslant\operatorname{tr}_hB=4K_h+|d\log\psi|_h^2$, $K_h\leqslant1$ and $\psi\leqslant1$, it follows that
\[
 2\pi\beta\leqslant\int_\Omega\psi^2(6+3K_h)\,dA_h+\int_\Omega|d\psi|_h^2\,dA_h\leqslant15\int_\Omega\psi^2\,dA_h\leqslant15\int_\Omega\psi\,dA_h,
\]
which is the lower bound of \eqref{eq:area-volume}, by \eqref{eq:volume-psi}.

\label{cor:volume-branch}
Along the branch from $g_1$, the function $\beta\mapsto\beta^{-1}\operatorname{Vol}(g_\beta)$ is nondecreasing, and, with $V_1:=\operatorname{Vol}(g_1)$,
\begin{equation}\label{eq:volume-lower}
 V_1\beta^5\leqslant\operatorname{Vol}(g_\beta)\leqslant \beta V_1.
\end{equation}

\label{lem:flattened-cores}
For $0<t<1$, the Friedrichs Dirichlet problem
\begin{equation}\label{eq:core-flattening}
 \Delta_h\sigma=K_h\quad\text{on }E_t,\qquad\text{and}\qquad \sigma|_{\partial E_t}=0
\end{equation}
has a unique solution, invariant under the central symmetries, with
\begin{equation}\label{eq:core-flattening-bound}
 |\sigma|\leqslant\tfrac14\log(\psi/t)\leqslant\tfrac14\log(1/t).
\end{equation}
The metric $\widetilde h=e^{2\sigma}h$ is flat away from $o$, has the same
cone angle at $o$, and satisfies
$t^{1/2}h\leqslant\widetilde h\leqslant t^{-1/2}h$.
For a smooth center, $\widetilde h$ is smooth and flat on all of $E_t$.

\label{lem:curv-central}
 For every compact interval $I\subset(0,1)$, there are $r_*,C>0$, depending only on $I$ and the symmetry class, such that every metric $g=g_{\beta,q}$ as in \eqref{eq:perturbed-metric} with $\beta\in I$ and $\mathcal E(\beta,q)=0$ satisfies
\begin{equation}\label{eq:curv-central}
 \sup_{\{0<d_g(\Sigma,\cdot)<r_*\}}|\operatorname{Rm}(g)|\leqslant C.
\end{equation}

\label{lem:torus-limit}


Let $(U_i,g_i,p_i)$ and $(\mathcal N,g_{\mathcal N},p)$ satisfy the two assumptions above.
\begin{enumerate}[label=\textup{(\alph*)}]
\item \emph{Limit action.} If corners $c_i\in U_i$ converge to $c\in\mathcal N$, then, after a subsequence, $X_{1,i},X_{2,i}$ converge smoothly on compact subsets to Killing vector fields $X_1,X_2$ of $g_{\mathcal N}$. They generate an effective isometric $\mathbb T^2$-action on $\mathcal N$, and on each ball about $c$ the convergence maps can be chosen equivariant. They then preserve the stabilizers, hence the rods, rod vectors and corners.
\item \emph{Existence of a corner.} If moreover $g_{\mathcal N}$ is nonflat and Ricci-flat, with finite curvature energy, then, after a subsequence, there are corners $c_i\in U_i$ converging to a point of $\mathcal N$.
\end{enumerate}

\label{prop:coord-compactness}
Assume \eqref{eq:coord-assumptions} and $\beta_i\to\beta_*\in I$. Then, after passing to a subsequence, there is an Einstein metric $g_\infty$ with cone angle $2\pi\beta_*$ along $\Sigma$, smooth across the rods and corners and satisfying the assumptions made on $g_*$ in Section~\ref{sec:spaces}, such that, in the prescribed coordinates \eqref{eq:fixed-cone-identification} and for $1<\nu<2$, we have
\begin{equation}\label{eq:coord-deformation-convergence}
 q_i=\bigl(\ell_i-\ell_\infty,\ \Phi_\infty\log(\Phi_\infty^{-1}\Phi_i),\
 a_i-a_\infty\bigr)\longrightarrow0\quad\text{in }\mathcal X^{2,\alpha}_\nu,
\end{equation}
where the space $\mathcal X^{2,\alpha}_\nu$ is centered at $g_\infty$.

\label{lem:curvature-localization}
The following hold for the sequence $(g_{Z,k})$.
\begin{enumerate}[label=\textup{(\roman*)}]
\item We have $\Lambda_k\to+\infty$.
\item Let $y_k\in Z^{(k)}$ and $r_k>0$ satisfy $Q_k:=|\operatorname{Rm}(g_{Z,k})|(y_k)\to+\infty$, $Q_kr_k^2\to+\infty$ and $|\operatorname{Rm}(g_{Z,k})|\leqslant4Q_k$ on $B_{g_{Z,k}}(y_k,r_k)$. Then, after a subsequence, $(Z^{(k)},Q_kg_{Z,k},y_k)$ converges smoothly on compact subsets to a complete, nonflat and Ricci-flat limit with an effective isometric action of $\mathbb R^2/2\pi\mathbb Z^2$, which has the original generators, rod vectors and rod and corner models, and no orbit with nontrivial finite stabilizer. Moreover, some corners $c_k\in\mathcal C_k$ satisfy $\sup_kQ_k^{1/2}d_{g_{Z,k}}(y_k,c_k)<+\infty$.
\item There is $C$ such that, for every $x\in Z^{(k)}$,
\begin{equation}\label{eq:curvature-away-corners}
 |\operatorname{Rm}(g_{Z,k})|(x)\,d_{g_{Z,k}}(x,\mathcal C_k)^2\leqslant C.
\end{equation}
\end{enumerate}

\label{lem:corner-noncollapse}
There are $L_k\to0$ and $C$ such that all corners $c,c'\in\mathcal C_k$ satisfy
\begin{equation}\label{eq:corner-noncollapse}
 d_{g_{Z,k}}(c,c')\leqslant CL_k\qquad\text{and}\qquad\operatorname{Vol}_{g_{Z,k}}B_{g_{Z,k}}(c,CL_k)\geqslant C^{-1}L_k^4.
\end{equation}

\label{prop:corner-compactness}
There is $C$ such that
\begin{equation}\label{eq:corner-distances}
 \pi\leqslant\Lambda_k^{1/2}d_{g_{Z,k}}(c,c')\leqslant C
\end{equation}
for all distinct $c,c'\in\mathcal C_k$. With $L_k$ as in Lemma~\ref{lem:corner-noncollapse}, we also have
\begin{equation}\label{eq:scale-comparison}
 C^{-1}\leqslant\Lambda_kL_k^2\leqslant C.
\end{equation}For $c_k\in\mathcal C_k$, a subsequence of $(Z^{(k)},\Lambda_kg_{Z,k},c_k)$ converges smoothly on compact subsets to a complete, nonflat and Ricci-flat $(X,g_X,c)$ with $|\operatorname{Rm}|\leqslant1$ and $\int_X|\operatorname{Rm}|^2\leqslant16\pi^2m$. 

The torus actions converge to an effective isometric action of $\mathbb R^2/2\pi\mathbb Z^2$ on $X$ with the original generators, rod vectors and rod and corner models, without orbits with nontrivial finite stabilizer, and the $\frac{m}{2}$ corners of $Z^{(k)}$ converge to the $\frac{m}{2}$ distinct corners of $X$.

\label{lem:weyl}
Let $X$ be as in Proposition~\ref{prop:corner-compactness}. Its orbit space $\overline\Omega_X:=X/\mathbb T^2$ is a closed half-cylinder, and on its interior there are coordinates $(\rho,z)$, with $z\in\mathbb R/P_{\mathrm W}\mathbb Z$ for some $P_{\mathrm W}>0$, in which locally
\begin{gather}
 g_X=e^{2a_{\mathrm W}}(d\rho^2+dz^2)+\rho\,\Phi_{ij}\,d\phi_i\,d\phi_j,\qquad\text{with}\qquad \rho=\sqrt{\det G}>0,\label{eq:weyl}\\
 \partial_\rho\bigl(\rho\,\Phi^{-1}\partial_\rho\Phi\bigr)+\partial_z\bigl(\rho\,\Phi^{-1}\partial_z\Phi\bigr)=0,\label{eq:weyl-harmonic}\\
 \partial_\rho a_{\mathrm W}=-\frac{1}{4\rho}+\frac{\rho}{4}\bigl(|\partial_\rho\Phi|_{\mathbb H^2}^2-|\partial_z\Phi|_{\mathbb H^2}^2\bigr),\qquad\text{and}\qquad \partial_za_{\mathrm W}=\frac{\rho}{2}\langle\partial_\rho\Phi,\partial_z\Phi\rangle_{\mathbb H^2},\label{eq:weyl-nu}\\
 K_h\leqslant0,\qquad |D\Phi|\leqslant\rho^{-1},\qquad\text{and}\qquad -\frac{1}{2\rho}\leqslant\partial_\rho a_{\mathrm W}\leqslant0,\label{eq:weyl-bounds}
\end{gather}
where $D$ is the flat derivative for $d\rho^2+dz^2$. The limit $\mathsf s$ of the isometries $\mathsf s_k$ of Section~\ref{subsec:models} acts by  $z\mapsto z+\frac{2P_{\mathrm W}}m$, so the rod endpoints are equally spaced in $z$, and
\begin{equation}\label{eq:weyl-shift}
 \Phi(\rho,z+\tfrac{2P_{\mathrm W}}m)=\iota\bigl(\Phi(\rho,z)\bigr).
\end{equation}
Going once around the $z$-circle does not translate the torus angles: the angular identification is $(z,\boldsymbol\phi)\sim(z+P_{\mathrm W},\boldsymbol\phi)$.

\label{conj:page}
For every $k\geqslant1$, the manifold
\[
 P_k=(2k+1)\mathbb{CP}^{2}\#(2k+1)\overline{\mathbb{CP}}{}^{2}
\]
admits a positive Einstein metric obtained by deforming the Page metric by allowing conical singularities along a torus fiber.

\label{lem:matrix-calculus}
Let $S\in\mathbb H^2$ and $\xi\in T_S\mathbb H^2$, with $|\xi|_S^2:=\frac{1}{2}\operatorname{tr}\bigl((S^{-1}\xi)^2\bigr)$.
\begin{enumerate}[label=\textup{(\roman*)}]
\item The exponential map of $g_{\mathbb H^2}$ is
\begin{equation}\label{eq:matrix-exp}
 \operatorname{Exp}_S\xi=S\exp(S^{-1}\xi)=\cosh(|\xi|_S)\,S+\frac{\sinh(|\xi|_S)}{|\xi|_S}\,\xi.
\end{equation}
\item For every $\Phi\in\mathbb H^2$, the projection \eqref{eq:matrix-projection} restricts to an isomorphism $\Pi_S:T_\Phi\mathbb H^2\to T_S\mathbb H^2$, equal to the identity if $\Phi=S$. Moreover $U:=\Pi_S\Phi\in T_S\mathbb H^2$ is a global coordinate on $\mathbb H^2$, with inverse $\Phi=\sqrt{1+|U|_S^2}\,S+U$ as in \eqref{eq:central-matrix-coordinate}.
\item The maps \eqref{eq:matrix-exp}, \eqref{eq:matrix-projection} and \eqref{eq:central-matrix-coordinate} commute with the congruences $S\mapsto P^{\mathsf T}SP$, $|\det P|=1$, hence with the target symmetries, and the tension field is \eqref{eq:matrix-tension}.

\end{enumerate}

\label{lem:division-lifts}

Let $0<\alpha<1$. All statements concern functions on a rod chart $\{x\geqslant0\}$ (resp. a corner chart $\{x,y\geqslant0\}$) of $\overline\Omega$, and a statement in the variable $x$ holds with $y$ as a parameter, with constants independent of $y$, and conversely.
\begin{enumerate}[label=\textup{(\alph*)}]
\item \emph{Division.} If $r,k,l\geqslant0$ are integers and $u\in C^{r+k+l,\alpha}$ has $\partial_x^iu=0$ on $\{x=0\}$ for $i<k$ and $\partial_y^iu=0$ on $\{y=0\}$ for $i<l$, then $u$ can be written as
\[
 u=x^ky^lw,\qquad\text{with}\qquad \|w\|_{C^{r,\alpha}}\leqslant C\|u\|_{C^{r+k+l,\alpha}}.
\] 
In particular, for even $F$ and odd $u$ in the $x$ variable, we have
\begin{gather}
 \frac{\partial_xF}x=\int_0^1\partial_x^2F(tx,y)\,dt,\label{eq:divided-even}\\
 \Bigl\|\frac{\partial_xF}x\Bigr\|_{C^{r,\alpha}}\leqslant C\|F\|_{C^{r+2,\alpha}},\label{eq:divided-even-norm}\\
 \frac{u}x=\int_0^1\partial_xu(tx,y)\,dt,\qquad\text{and}\qquad
 \frac{u_x}x-\frac{u}{x^2}=\int_0^1t\,u_{xx}(tx,y)\,dt.\label{eq:divided-odd}
\end{gather}
At $x=0$, \eqref{eq:divided-even} gives $x^{-1}\partial_xF=\partial_x^2F$. Consequently, we have
\[
 \Bigl\|\frac{u}x\Bigr\|_{C^{r,\alpha}}\leqslant C\|u\|_{C^{r+1,\alpha}},\qquad\text{and}\qquad
 \Bigl\|\frac{u_x}x-\frac{u}{x^2}\Bigr\|_{C^{r,\alpha}}\leqslant C\|u\|_{C^{r+2,\alpha}}.
\]
\item \emph{Euclidean lifts.} For $j\in\{1,2\}$, even $\varphi$ and $u$ odd in each variable, the lifts $\mathcal L_j\varphi$ and $\mathcal L_\perp u$ above satisfy, for every integer $r\geqslant0$,
\begin{equation}\label{eq:lift-norms}
\begin{aligned}
 C^{-1}\|\varphi\|_{C^{r,\alpha}_{\mathrm{ev}}}\leqslant \|\mathcal L_j\varphi\|_{C^{r,\alpha}}&\leqslant C\|\varphi\|_{C^{r,\alpha}_{\mathrm{ev}}},&\qquad
 \Delta\mathcal L_j\varphi&=\mathcal L_j(D_j\varphi),\\
C^{-1}\|u\|_{C^{r,\alpha}_{\mathrm{odd}}} \leqslant \|\mathcal L_\perp u\|_{C^{r,\alpha}}&\leqslant C\|u\|_{C^{r,\alpha}_{\mathrm{odd}}},&
 \Delta\mathcal L_\perp u&=\mathcal L_\perp(D_\perp u).
\end{aligned}
\end{equation}
For $r\geqslant2$ the Laplacian identities hold pointwise. 
 \item \emph{Energy and weak equations.} For a corner chart $U$, put $\widetilde U_j:=\{(Z,Z')\in\mathbb R^{j+1}\times\mathbb R^{j+1}:(|Z|,|Z'|)\in U\}$. Polar integration gives
\begin{equation}\label{eq:lift-energy}
\begin{aligned}
 \|\mathcal L_j\varphi\|_{H^1(\widetilde U_j)}^2&=|\mathbb S^j|^2\!\int_U x^jy^j\bigl(\varphi^2+|d\varphi|_0^2\bigr)\,dx\,dy,\\
 \|\mathcal L_\perp u\|_{H^1(\widetilde U_1)}^2&=(2\pi)^2\!\int_U xy\bigl(|du|_0^2+(1+x^{-2}+y^{-2})u^2\bigr)\,dx\,dy.
\end{aligned}
\end{equation}


Thus the lifts $\mathcal L_j$ and $\mathcal L_\perp$ extend, isometrically up to the factors $|\mathbb S^j|$ and $2\pi$, to the completions of the smooth even, respectively odd, profiles on the quadrant for the weighted energies in \eqref{eq:lift-energy}, with values in $H^1$. For smooth even $\kappa,c$, writing tildes for their radial lifts {to $\mathbb R^{j+1}\times\mathbb R^{j+1}$},
\begin{equation}\label{eq:weak-lift}
 (\Delta+\langle d\widetilde\kappa,d\,\cdot\,\rangle-\widetilde c)\,\mathcal L_j\varphi
 =\mathcal L_j\bigl(D_j\varphi+\langle d\kappa,d\varphi\rangle_0-c\varphi\bigr)
\end{equation}
holds also weakly: tests on the quadrant use the measure $x^jy^je^\kappa\,dx\,dy$, and tests after lifting use $e^{\widetilde\kappa}dZ\,d{Z'}$. The identity $\Delta\mathcal L_\perp u=\mathcal L_\perp(D_\perp u)$ has the analogous weak interpretation in the energy norm in \eqref{eq:lift-energy}.
\end{enumerate}

\label{lem:regularized-equations}

In a corner chart, with the connection form \eqref{eq:connection-form-local}, substituting $\rho=xye^{\widehat\ell}$, $s=\log(y/x)+\widehat s$ and $\omega=(y/x)\widehat\omega$ in \eqref{eq:conic-map} gives
\begin{equation}\label{cmp:nonlinear-first-residuals}
\begin{aligned}
 e^{2c_\gamma}\mathcal E_1&=D_2\widehat\ell+|d\widehat\ell|_0^2+6e^{2\widehat a},\\
 e^{2c_\gamma}\mathcal H_s&=D_1\widehat s+\langle d\widehat\ell,d\widehat s\rangle_0-\frac{\partial_x\widehat\ell}x+\frac{\partial_y\widehat\ell}y+|A_\Phi|_0^2,\\
 e^{2c_\gamma}\mathcal H_\perp&=e^{-\widehat s}D_\perp\widehat\omega+\langle d\widehat\ell-2d\widehat s,A_\Phi\rangle_0,\\
 e^{2c_\gamma}\mathcal E_3&=\Delta_0\widehat a-\frac{1}{2}\Bigl(\frac{\partial_x(\widehat\ell+\widehat s)}x+\frac{\partial_y(\widehat\ell-\widehat s)}y\Bigr)
   +\frac{1}{4}\bigl(|d\widehat s|_0^2-|d\widehat\ell|_0^2+|A_\Phi|_0^2\bigr).
\end{aligned}
\end{equation}
The right-hand side of the third line is odd in each variable, and the four right-hand sides are smooth maps of $q\in\mathcal U_0$ into $C^{0,\alpha}$, respectively $C^{0,\alpha}_{\mathrm{odd}}$ for the third line. The rod case follows  with the rod convention of Section~ \ref{subsec:division-lifts}.
